//go:build arm64

package floats

// NEON kernels of the correctly rounded float32 Exp and Log, generated by
// go-asmgen (explog_arm64_gen.go) into explog_arm64.s: go-ndarray#95
// (perf/exp32-neon), proven correctly rounded over all 2^32 float32 on
// darwin/arm64, Zen 3, POWER9 and s390x z17, moved here as K1 of the go-scikit
// performance campaign. They run the Go transcriptions' operations in their
// order (expCR fuses exactly where cr_expf does: VFMLA/VFMLS round once, as
// math.FMA does; logCR keeps every product unfused), so the SIMD blocks and the
// Go blocks agree bit for bit; a block of 8 holding a lane the kernel does not
// finish is not stored, it is handed back to Go. float64 Log and Exp run the Go
// loops here (no NEON kernel yet).

// expCRNEONConsts is the constant block exp32CRNEON reads (explog_arm64_gen.go,
// exp32CRKernel) into V16-V26, then the table it indexes.
type expCRNEONConsts struct {
	shift, invLn2, ln2Hi, ln2Lo [2]float64 // offsets 0, 16, 32, 48
	c0, c1, c2, c3              [2]float64 // 64, 80, 96, 112
	idxMask, expMask            [2]uint64  // 128, 144
	lim                         [4]float32 // 160
	table                       [64]uint64 // 176
}

var expCRKN = func() *expCRNEONConsts {
	k := new(expCRNEONConsts)
	for i := range 2 {
		k.shift[i], k.invLn2[i], k.ln2Hi[i], k.ln2Lo[i] = crShift, crInvLn2, crLn2Hi, crLn2Lo
		k.c0[i], k.c1[i], k.c2[i], k.c3[i] = crC0, crC1, crC2, crC3
		k.idxMask[i], k.expMask[i] = 63, 0xfff0000000000000
	}
	k.lim = [4]float32{512, 512, 512, 512}
	k.table = crMant
	return k
}()

// exp32Fast is the correctly rounded float32 exp: blocks of 8 on the NEON
// kernel, which hands back each block holding a lane with |x| > 512 or a NaN
// to exp32CR, as is the tail. Both run expCR's operations in its order, so
// they agree bit for bit.
func exp32Fast(dst, src []float32) {
	src = src[:len(dst)]
	i, n := 0, len(dst)&^7
	for i < n {
		i += exp32CRNEON(&dst[i], &src[i], n-i, expCRKN)
		if i < n {
			exp32CR(dst[i:i+8], src[i:i+8])
			i += 8
		}
	}
	exp32CR(dst[i:], src[i:])
}

//go:noescape
func exp32CRNEON(dst, src *float32, n int, k *expCRNEONConsts) (done int)

// logCRNEONConsts is the constant block log32CRNEON loads into V16-V28
// (explog_arm64_gen.go, log32CRKernel), then the tables it indexes.
type logCRNEONConsts struct {
	one, ln2, b0, b1, b2, w               [2]float64  // offsets 0, 16, 32, 48, 64, 80
	mmask, jadd, bias, sub, maxv, oneBits [4]uint32   // 96, 112, 128, 144, 160, 176
	expOr                                 [2]uint64   // 192
	tr, tl                                [65]float64 // 208, 728
}

var logCRKN = func() *logCRNEONConsts {
	k := new(logCRNEONConsts)
	for i := range 2 {
		k.one[i], k.ln2[i], k.w[i] = 1, 0x1.62e42fefa39efp-1, 0x1.f06p-33
		k.b0[i], k.b1[i], k.b2[i] = logCRB[0], logCRB[1], logCRB[2]
		k.expOr[i] = 1023 << 23
	}
	for i := range 4 {
		k.mmask[i], k.jadd[i], k.bias[i] = 1<<23-1, 1<<16, 127
		// The positive-normal test: ux + sub (wrapping) <= maxv as int32.
		k.sub[i], k.maxv[i], k.oneBits[i] = 0x7f800000, 0xfeffffff, 0x3f800000
	}
	k.tr, k.tl = logCRTr, logCRTl
	return k
}()

// log32Fast is the correctly rounded float32 log: blocks of 8 on the NEON
// kernel, which hands back each block it cannot finish (an input that is not
// a positive normal float32, or bounds that round apart) to logCR, as is the
// tail. Both run logCR's operations in its order, so they agree bit for bit.
func log32Fast(dst, src []float32) {
	src = src[:len(dst)]
	i, n := 0, len(dst)&^7
	for i < n {
		i += log32CRNEON(&dst[i], &src[i], n-i, logCRKN)
		if i < n {
			logCRSlice(dst[i:i+8], src[i:i+8])
			i += 8
		}
	}
	logCRSlice(dst[i:], src[i:])
}

//go:noescape
func log32CRNEON(dst, src *float32, n int, k *logCRNEONConsts) (done int)

// logFast is Log's Go loop on arm64 (no NEON kernel for float64 yet).
func logFast(dst, src []float64) { logScalar(dst, src) }
